---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Meeting card: The next meeting from countdown to wrap-up, with the time already gone hatched out and a join that stays open.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change meeting-card.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './meeting-card.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'wide', className]} data-c="meeting-card" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="mtx panel">
  <div class="mtx-h">
    <b class="mtx-t">Pricing review</b><span class="mtx-sub num">Today, 10:30 to 11:15</span>
    <span class="tag mtx-st"><span><svg class="i xs"><use href="#i-clock"/></svg>In <span class="mtx-roll num"><i>10</i></span> min</span></span>
  </div>
  <div class="mtx-track" role="img" aria-label="Now 10:20. The meeting runs 10:30 to 11:15">
    <span class="mtx-blk"><span class="mtx-bp"></span><span class="num">10:30</span><span class="num">11:15</span></span>
    <span class="mtx-now"><i></i></span>
  </div>
  <div class="mtx-f">
    <div class="mtx-who"><span class="av" style="background:var(--dm-av-l);color:var(--dm-av-l-ink)" role="img" aria-label="Maya Kim" data-tip="Maya Kim">MK</span><span class="av" style="background:var(--dm-av-m);color:var(--dm-av-m-ink)" role="img" aria-label="Jo Ortiz" data-tip="Jo Ortiz">JO</span><span class="av" style="background:var(--dm-av-p);color:var(--dm-av-p-ink)" role="img" aria-label="Ana Ruiz" data-tip="Ana Ruiz">AR</span><span class="av" style="background:var(--dm-av-t);color:var(--dm-av-t-ink)" role="img" aria-label="Sam Lee" data-tip="Sam Lee">SL</span><span class="av mtx-more" role="img" aria-label="Dev Kapoor, Lena Novak" data-tip="Dev Kapoor, Lena Novak">+2</span></div>
    <span class="sp"></span>
    <button class="ib mtx-cp" aria-label="Copy Google Meet link" data-tip="Copy meet.google.com/nax-wqkf-stu"><svg class="i s"><use href="#i-link"/></svg></button>
    <button class="pill primary mtx-join"><span class="mk"><svg class="brand" aria-hidden="true" viewBox="0 0 87.5 72"><path fill="#00832d" d="M49.5 36l8.53 9.75 11.47 7.33 2-17.02-2-16.64-11.69 6.44z"/><path fill="#0066da" d="M0 51.5V66c0 3.315 2.685 6 6 6h14.5l3-10.96-3-9.54-9.95-3z"/><path fill="#e94235" d="M20.5 0L0 20.5l10.55 3 9.95-3 2.95-9.41z"/><path fill="#2684fc" d="M20.5 20.5H0v31h20.5z"/><path fill="#00ac47" d="M82.6 8.68L69.5 19.42v33.66l13.16 10.79c1.97 1.54 4.85.135 4.85-2.37V11c0-2.535-2.945-3.925-4.91-2.32zM49.5 36v15.5h-29V72h43c3.315 0 6-2.685 6-6V53.08z"/><path fill="#ffba00" d="M63.5 0h-43v20.5h29V36l20-16.57V6c0-3.315-2.685-6-6-6z"/></svg></span><span class="lb">Join</span></button>
  </div>
</div>
  </Fragment></div>
</div>
<script>
  import './meeting-card.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Meeting card ---------- */
/* the next meeting, told as it goes: a countdown, "Starting now", the meeting in progress and then over. The track is the
   morning from 10:00 to 12:30 with the meeting on it in the accent tint, its start and end on the block itself. Time that
   has gone is hatched out in neutral grey (the hatch and the tint meet at the now line), and the status chip at the top right
   rolls its minutes. Join stays open while the meeting runs, since people join late, and breathes gently while it is live.
   Every state is the same height */
.mtx{width:100%;max-width:400px;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-4)}
/* the title and the chip share the first line; the time runs under both, so a longer chip never wraps it and every state
   is the same height */
.mtx-h{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;column-gap:var(--dm-s-3);row-gap:2px}
.mtx-t{font-size:14px;font-weight:500;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mtx-sub{grid-row:2;grid-column:1 / -1;font-size:12.5px;color:var(--dm-muted)}
.mtx-st{grid-row:1;grid-column:2;justify-self:end;transition:background .4s cubic-bezier(.22,1,.36,1),color .4s cubic-bezier(.22,1,.36,1)}
.mtx-st>span{display:inline-flex;align-items:center;gap:5px}
.mtx-st .dot{color:var(--dm-ok-mark)}
.mtx-fade{animation:mtxfade .4s cubic-bezier(.22,1,.36,1) both}
@keyframes mtxfade{from{opacity:0}}
/* the minutes roll: each new number comes up from below */
.mtx-roll{display:inline-grid;overflow:hidden;line-height:20px;height:20px}
.mtx-roll i{font-style:normal}
.mtx-roll i.in{animation:mtxroll .32s cubic-bezier(.22,1,.36,1) both}
@keyframes mtxroll{from{transform:translateY(70%);opacity:0}}
/* the track: the morning on a quiet row, the meeting on it */
.mtx-track{position:relative;height:40px;border-radius:calc(8px * var(--dm-rk));background:var(--dm-row);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);overflow:hidden}
/* Blueprint's row is the surface itself: its green now line keeps 3:1 on white, not on the row grey */
:root:not([data-style="soft"]) .mtx-track:not(:where([data-style="soft"],[data-style="soft"] *)){background:var(--dm-surface)}
.mtx-blk{position:absolute;top:5px;bottom:5px;left:20%;width:60%;display:flex;align-items:center;justify-content:space-between;padding:0 var(--dm-s-2);border-radius:calc(5px * var(--dm-rk));background:var(--dm-accent-bg);overflow:hidden;font-size:11.5px;font-weight:500;color:var(--dm-fg2);z-index:1}
/* the start and end sit on the block in small surface chips, so they read on the tint and on the hatch alike; the block's
   edge is a faint accent line (owner, 17 Nov: no grey outline) */
.mtx-blk{outline:1px solid color-mix(in srgb,var(--dm-accent-mark) 35%,transparent);outline-offset:-1px}
.mtx-blk>.num{position:relative;padding:1px 5px;border-radius:calc(4px * var(--dm-rk));background:color-mix(in srgb,var(--dm-surface) 88%,transparent);color:var(--dm-fg2)}
/* gone: fine 45deg accent lines over the tint, inside the meeting block only, across the part that has run (owner, 17 Nov) */
.mtx-bp{position:absolute;top:0;bottom:0;left:0;background:repeating-linear-gradient(45deg,color-mix(in srgb,var(--dm-accent-mark) 60%,transparent) 0 1px,transparent 1px 6px);transition:width .45s cubic-bezier(.22,1,.36,1)}
.mtx-bp{width:var(--dm-cut,0%)}
.mtx-now{position:absolute;top:0;bottom:0;left:var(--dm-p,0%);width:2px;margin-left:-1px;background:var(--dm-accent-mark);transition:left .45s cubic-bezier(.22,1,.36,1);z-index:2}
.mtx-now i{position:absolute;top:3px;left:50%;width:6px;height:6px;margin-left:-3px;border-radius:50%;background:var(--dm-accent-mark)}
.mtx.done .mtx-now{opacity:0;transition:opacity .4s,left .45s cubic-bezier(.22,1,.36,1)}
/* the footer: who is coming, the link, and Join */
.mtx-f{display:flex;align-items:center;gap:var(--dm-s-2)}
.mtx-who{display:flex;align-items:center;padding:2px 0}
.mtx-who .av{width:26px;height:26px;font-size:10px;margin-left:-4px;box-shadow:0 0 0 2px var(--dm-surface);transition:margin .25s cubic-bezier(.22,1,.36,1)}
.mtx-who .av:first-child{margin-left:0}
@media (hover:hover) and (pointer:fine){.mtx-who:is(:hover,.hv) .av:not(:first-child){margin-left:2px}}
.mtx-who .mtx-more{background:var(--dm-chip);color:var(--dm-fg2)}
.mtx-cp{width:34px;height:34px}
.mtx-join{height:34px;padding:0 var(--dm-s-4) 0 6px;gap:var(--dm-s-2);transition:background var(--dm-t-fast),opacity var(--dm-t-fast),transform .32s cubic-bezier(.34,1.56,.64,1)}
.mtx-join:active,.mtx-join.prs{transform:scale(.95);transition-duration:.08s}
.mtx-join .mk{width:22px;height:22px;display:grid;place-items:center;border-radius:calc(6px * var(--dm-rk));background:#fff;flex:none}
.mtx-join .mk .brand{width:15px;height:12.5px}
/* live: Join breathes a step darker and back, slowly; a darker fill keeps its label's contrast where fading it would not */
.mtx.live .mtx-join:not(:hover){animation:mtxpulse 2.4s ease-in-out infinite}
@keyframes mtxpulse{50%{background:color-mix(in srgb,var(--dm-accent) 86%,#000)}}
.mtx-join[disabled] .mk{opacity:.5}
@media (prefers-reduced-motion:reduce){.mtx.live .mtx-join{animation:none}.mtx-bp,.mtx-now,.mtx-who .av{transition:none}.mtx-roll i.in,.mtx-fade{animation:none}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, BRAND, DM, I, copied, swap } from '../core/core.js';
DM.def('meeting-card', (r, c) => {
  r.innerHTML = r.innerHTML.replace(/\{([\w-]+)\}/g, (m, k) => k === 'meet' ? BRAND.meet : I(k, k === 'clock' ? 'xs' : 's'));
  // the row runs 10:15 to 11:30 in minutes of the day; the meeting is 10:30 to 11:15, 45 minutes
  const FROM = 615, TO = 690, AT = 630, END = 675, URL = 'https://meet.google.com/nax-wqkf-stu';
  const pc = m => Math.min(100, Math.max(0, (m - FROM) / (TO - FROM) * 100));
  const clock = m => `${Math.floor(m / 60)}:${String(m % 60).padStart(2, '0')}`;
  const root = $('.mtx', r), st = $('.mtx-st', r), track = $('.mtx-track', r), blk = $('.mtx-blk', r), join = $('.mtx-join', r), cp = $('.mtx-cp', r);
  const phase = m => m < AT ? 'soon' : m === AT ? 'start' : m < END ? 'live' : 'done';
  let was = 'soon', num = 10;
  // the chip: a new state fades in; within a state only the minutes change, and they roll
  const chip = (cls, inner) => { st.className = 'tag mtx-st' + (cls ? ' ' + cls : ''); st.innerHTML = `<span class="mtx-fade">${inner}</span>`; };
  const roll = n => { const el = $('.mtx-roll', st); if (el && n !== num) el.innerHTML = `<i class="in">${n}</i>`; num = n; };
  const set = m => {
    const ph = phase(m), p = pc(m);
    root.style.setProperty('--dm-p', p + '%'); track.style.setProperty('--dm-p', p + '%');
    blk.style.setProperty('--dm-cut', Math.min(100, Math.max(0, (m - AT) / (END - AT) * 100)) + '%');
    const n = ph === 'soon' ? AT - m : END - m;
    if (ph !== was){
      if (ph === 'soon') chip('', `${I('clock', 'xs')}In <span class="mtx-roll num"><i>${n}</i></span> min`);
      if (ph === 'start') chip('ok', '<i class="dot"></i>Starting now');
      if (ph === 'live') chip('ok', `<i class="dot"></i>Live, <span class="mtx-roll num"><i>${n}</i></span> min left`);
      if (ph === 'done') chip('', 'Ended');
      num = n;
    } else roll(n);
    was = ph;
    root.classList.toggle('live', ph === 'start' || ph === 'live');
    root.classList.toggle('done', ph === 'done');
    join.disabled = ph === 'done';
    track.setAttribute('aria-label', ph === 'done' ? 'The meeting ran 10:30 to 11:15 and has ended' : `Now ${clock(m)}. The meeting runs 10:30 to 11:15`);
  };
  set(620);
  join.onclick = () => {
    join.classList.add('prs'); c.later(110, () => join.classList.remove('prs'));
    const lb = $('.lb', join); swap(lb, 'Opening Meet'); c.later(1600, () => swap(lb, 'Join'));
  };
  cp.onclick = () => copied(cp, URL, 'Copied');
  const who = $('.mtx-who', r);
  // the preview: the countdown, "Starting now", the meeting going by with the gone part hatched, then over
  c.story(async s => {
    await s.beat(2);
    for (let m = 621; m <= AT; m++){ await s.beat(1); set(m); }
    await s.beat(4);
    for (let m = AT + 3; m <= 651; m += 3){ await s.beat(1.2); set(m); }
    who.classList.add('hv'); await s.point($$('.av', who)[1]); await s.beat(3);
    who.classList.remove('hv'); await s.tap(cp); await s.beat(3);
    s.away();
    for (let m = 654; m <= END; m += 3){ await s.beat(1.2); set(m); }
    await s.beat(5);
  });
});
